class UserProfile {
  late String _name; // _name is non-nullable, but initialized late

  // Simulate fetching user data asynchronously
  Future<void> fetchUserData() async {
    // In a real app, this would involve network calls or database reads
    await Future.delayed(Duration(seconds: 1));
    _name = "Alice"; // Initialize _name here
    print("User data fetched and name is set.");
  }

  void printUserName() {
    // This will throw an error if fetchUserData() hasn't completed yet
    print("Username: $_name");
  }
}

void main() async {
  var profile = UserProfile();

  // If we call printUserName() here, it will cause a runtime error because _name is not yet initialized.
  // profile.printUserName(); // Uncommenting this would lead to an error

  await profile.fetchUserData(); // Wait for data to be fetched and _name to be initialized
  profile.printUserName(); // Now this is safe
}
