class Example {
  // Option 1: Nullable field
  String? optionalValue;

  // Option 2: Late non-nullable field
  late String requiredValue;

  // Option 3: Immediately initialized non-nullable field
  String immediateValue = "Default";

  Example() {
    // For 'requiredValue', we must initialize it here or in an initializer list.
    // If we don't, it's a compile-time error.
    requiredValue = "Initialized in constructor";
  }

  void processValues() {
    // With nullable, you need checks
    if (optionalValue != null) {
      print("Optional: $optionalValue");
    } else {
      print("Optional value is null.");
    }

    // With late, you can access directly (assuming it's initialized)
    print("Required: $requiredValue");

    // With immediate, you can access directly
    print("Immediate: $immediateValue");
  }
}

void main() {
  var instance = Example();

  // instance.optionalValue is initially null
  instance.processValues();
  // Output:
  // Optional value is null.
  // Required: Initialized in constructor
  // Immediate: Default

  instance.optionalValue = "Some data";
  instance.processValues();
  // Output:
  // Optional: Some data
  // Required: Initialized in constructor
  // Immediate: Default

  // If we tried to access requiredValue before it was initialized (e.g., if it wasn't in the constructor)
  // var anotherInstance = Example();
  // anotherInstance.requiredValue; // This would throw a runtime error.
}
